  App.modal = o.kind || 'x';
  const lh = o.kind !== 'setup' && App.S ? '<div class="lh">' + crest(App.S.colors, App.S.emblem, 22) + '<b>' + esc(App.S.name) + '</b><i>' + esc(App.S.motto) + '</i></div>' : '';
